#ifndef VEXEL_SVG_SHAPE_H
#define VEXEL_SVG_SHAPE_H

#include "base.h"
#include "geometry.h"
#include "media.h"
#include "../animation/animation.h"
#include "xml_tokenizer.h"

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* Document-wide flattened-edge budget. Every line segment of every path becomes
 * one edge, so a drawing made of thousands of small paths exceeded 262144 long
 * before it was large. The bound stays finite so a pathological input is still
 * refused. */
#define SVG_SHAPE_MAX_EDGES (4U * 1024U * 1024U)
/* Shape (path/element) budget. 65536 elements is already far beyond any hand
 * authored document, so a file with more is refused rather than rendered. */
#define SVG_SHAPE_MAX_SHAPES 65536U
/* Per-path command budget. A single CAD path routinely carries hundreds of
 * thousands of segments, so 65536 refused ordinary drawings. */
#define SVG_SHAPE_MAX_COMMANDS (4U * 1024U * 1024U)
#define SVG_SHAPE_MAX_DASH_VALUES 16U
#define SVG_SHAPE_MAX_PATH_NUMBERS (SVG_SHAPE_MAX_COMMANDS * 7U)

typedef enum svg_shape_linecap { SVG_SHAPE_CAP_BUTT, SVG_SHAPE_CAP_SQUARE, SVG_SHAPE_CAP_ROUND } svg_shape_linecap;
typedef enum svg_shape_linejoin { SVG_SHAPE_JOIN_MITER, SVG_SHAPE_JOIN_BEVEL, SVG_SHAPE_JOIN_ROUND } svg_shape_linejoin;
typedef struct svg_shape_stroke {
    uint8_t rgba[4];
    double width;
    double miter_limit;
    double dash_offset;
    uint32_t dash_value_start;
    uint8_t dash_count;
    svg_shape_linecap cap;
    svg_shape_linejoin join;
    bool paint_server;
    bool crisp_edges;
    uint8_t paint_order;
} svg_shape_stroke;
typedef struct svg_shape_path_subpath {
    size_t first_edge;
    size_t edge_count; /* includes the implicit fill-closing edge */
    bool closed;       /* whether closepath explicitly closes the stroke path */
} svg_shape_path_subpath;
#define SVG_SHAPE_MAX_FILTER_PRIMITIVES 16U
#define SVG_SHAPE_MAX_FILTER_MERGE_INPUTS 8U
typedef enum svg_shape_filter_kind {
    SVG_SHAPE_FILTER_GAUSSIAN_BLUR,
    SVG_SHAPE_FILTER_OFFSET,
    SVG_SHAPE_FILTER_FLOOD,
    SVG_SHAPE_FILTER_BLEND,
    SVG_SHAPE_FILTER_COMPOSITE,
    SVG_SHAPE_FILTER_MERGE,
    SVG_SHAPE_FILTER_COLOR_MATRIX,
    SVG_SHAPE_FILTER_DROP_SHADOW
} svg_shape_filter_kind;

#define SVG_SHAPE_FILTER_INPUT_PREVIOUS (-1)
#define SVG_SHAPE_FILTER_INPUT_GRAPHIC (-2)
#define SVG_SHAPE_FILTER_INPUT_ALPHA (-3)
typedef struct svg_shape_filter_primitive {
    svg_shape_filter_kind kind;
    int32_t input;
    int32_t input2;
    int32_t merge_inputs[SVG_SHAPE_MAX_FILTER_MERGE_INPUTS];
    uint8_t merge_count;
    uint8_t mode;
    uint8_t rgba[4];
    double values[20];
    size_t source_offset;
} svg_shape_filter_primitive;

typedef struct svg_shape_filter {
    size_t first_primitive;
    size_t primitive_count;
    bool linear_rgb;
    bool filter_units_object_bounding_box;
    bool primitive_units_object_bounding_box;
    bool custom_region;
    double region[4];
} svg_shape_filter;

typedef struct svg_shape_document svg_shape_document;
#define SVG_SHAPE_MAX_MASKS 4096U
#define SVG_SHAPE_NO_MASK SIZE_MAX
typedef struct svg_shape_mask {
    svg_shape_document *content;
    bool luminance;
    bool region_object_bounding_box;
    bool custom_region;
    double region[4];
    geom_affine region_transform;
    size_t source_offset;
} svg_shape_mask;

#define SVG_SHAPE_MAX_PATTERNS 4096U
#define SVG_SHAPE_MAX_PATTERN_BYTES (16U * 1024U * 1024U)
#define SVG_SHAPE_NO_PATTERN SIZE_MAX
typedef struct svg_shape_pattern {
    uint8_t *rgba;
    size_t byte_count;
    uint32_t width;
    uint32_t height;
    size_t definition_element;
    double tile_width;
    double tile_height;
    geom_affine content_transform;
} svg_shape_pattern;

#define SVG_SHAPE_NO_FILTER SIZE_MAX
typedef struct svg_shape_opacity_group {
    size_t first_shape;
    size_t end_shape;
    size_t parent;
    double opacity;
    size_t filter_index;
    size_t mask_index;
    uint8_t blend_mode;
    bool isolation;
} svg_shape_opacity_group;
#define SVG_SHAPE_NO_GROUP SIZE_MAX
typedef struct svg_shape_aspect {
    double align_x;
    double align_y;
    bool none;
    bool slice;
    bool set;
} svg_shape_aspect;

typedef struct svg_shape_paint svg_shape_paint;
typedef struct svg_paint_stop svg_paint_stop;
typedef struct svg_shape_clip svg_shape_clip;

/* Returns NULL when the shape uses the default solid fill. */
const svg_shape_paint *svg_shape_paint_for_shape(
    const svg_shape_document *document, size_t shape_index);
svg_shape_paint *svg_shape_paint_for_shape_mutable(
    svg_shape_document *document, size_t shape_index);
/* Returns NULL when the shape uses the default solid stroke. */
const svg_shape_paint *svg_shape_stroke_paint_for_shape(
    const svg_shape_document *document, size_t shape_index);
svg_shape_paint *svg_shape_stroke_paint_for_shape_mutable(
    svg_shape_document *document, size_t shape_index);
const double *svg_shape_stroke_dash_values_for_shape(
    const svg_shape_document *document, size_t shape_index);

typedef struct svg_shape_source_map {
    size_t offset;
    size_t length;
    geom_affine transform;
    size_t transform_node;
} svg_shape_source_map;

#define SVG_SHAPE_NO_TRANSFORM_NODE SIZE_MAX
typedef struct svg_shape_transform_frame {
    size_t source_offset;
    size_t parent;
    geom_affine attribute;
    geom_affine suffix;
    geom_affine motion;
} svg_shape_transform_frame;

typedef struct svg_shape_path_number {
    size_t offset;
    size_t length;
    double value;
} svg_shape_path_number;

typedef struct svg_shape_path_segment {
    char command; /* authored command, including relative/absolute case */
    size_t source_offset;
    size_t source_length;
    size_t command_offset; /* SIZE_MAX for an implicit repeated command */
    size_t first_number;
    size_t number_count;
    size_t first_edge;
    size_t edge_count;
    size_t shape_index;
} svg_shape_path_segment;

typedef struct svg_shape_image {
    const uint8_t *rgba; /* provider-owned premultiplied RGBA8 */
    size_t byte_count;
    size_t row_stride;
    uint32_t pixel_width;
    uint32_t pixel_height;
    void *owner;
    double x;
    double y;
    double width;
    double height;
    double draw_x;
    double draw_y;
    double draw_width;
    double draw_height;
} svg_shape_image;

typedef enum svg_shape_error {
    SVG_SHAPE_ERROR_NONE = 0,
    SVG_SHAPE_ERROR_INVALID_ARGUMENT,
    SVG_SHAPE_ERROR_XML,
    SVG_SHAPE_ERROR_UNSUPPORTED,
    SVG_SHAPE_ERROR_NUMBER,
    SVG_SHAPE_ERROR_LIMIT,
    SVG_SHAPE_ERROR_PATH,
    SVG_SHAPE_ERROR_VIEWPORT,
    SVG_SHAPE_ERROR_OOM,
    SVG_SHAPE_ERROR_UNSUPPORTED_FE_TURBULENCE,
    SVG_SHAPE_ERROR_UNSUPPORTED_FE_DISPLACEMENT_MAP,
    SVG_SHAPE_ERROR_UNSUPPORTED_FE_CONVOLVE_MATRIX,
    SVG_SHAPE_ERROR_UNSUPPORTED_FE_IMAGE,
    SVG_SHAPE_ERROR_UNSUPPORTED_FE_LIGHTING,
    SVG_SHAPE_ERROR_UNSUPPORTED_FE_MORPHOLOGY
} svg_shape_error;

typedef struct svg_shape_diagnostic { svg_shape_error category; size_t offset; } svg_shape_diagnostic;
/* Constructs the decoder deliberately ignores for rendering (ADR-0016 decision 5).
 * The source is untouched; this only reports what was skipped. */
typedef enum svg_shape_ignored_kind {
    SVG_SHAPE_IGNORED_UNKNOWN_ATTRIBUTE = 0,
    SVG_SHAPE_IGNORED_META,
    SVG_SHAPE_IGNORED_DOCTYPE,
    SVG_SHAPE_IGNORED_WRITING_MODE,
    SVG_SHAPE_IGNORED_KIND_COUNT
} svg_shape_ignored_kind;
typedef struct svg_shape_ignored {
    size_t count;
    size_t first_offset; /* meaningful only when count != 0 */
} svg_shape_ignored;
const char *svg_shape_ignored_kind_name(svg_shape_ignored_kind kind);

struct svg_shape_document {
    uint32_t width;
    uint32_t height;
    double view_x, view_y, view_width, view_height;
    svg_shape_aspect preserve_aspect;
    size_t edge_count;
    geom_edge *edges;
    uint8_t *colors; /* one owned RGBA color per edge */
    uint32_t *shape_ids; /* edge-to-element map; preserves independent fills */
    size_t shape_count;
    bool *shape_evenodd; /* one fill rule per shape element */
    bool *shape_filled; /* false for open line geometry, which awaits stroke */
    bool *shape_stroke_closed;
    size_t *shape_edge_start;
    size_t *shape_edge_count;
    size_t *shape_subpath_start;
    size_t *shape_subpath_count;
    svg_shape_path_subpath *path_subpaths;
    size_t path_subpath_count;
    svg_shape_path_segment *path_segments;
    size_t path_segment_count;
    svg_shape_path_number *path_numbers;
    size_t path_number_count;
    svg_shape_source_map *shape_sources;
    svg_shape_transform_frame *transform_nodes;
    size_t transform_node_count;
    svg_shape_image *images; /* one optional provider-owned image per shape */
    void *media_context;
    svg_shape_image_release_fn release_image;
    svg_shape_opacity_group *opacity_groups;
    size_t opacity_group_count;
    svg_shape_filter *filters;
    size_t filter_count;
    svg_shape_filter_primitive *filter_primitives;
    size_t filter_primitive_count;
    svg_shape_mask *masks;
    size_t mask_count;
    svg_shape_pattern *patterns;
    size_t pattern_count;
    size_t pattern_bytes;
    geom_affine *shape_stroke_inverse;
    svg_shape_stroke *strokes;
    svg_shape_paint *paints; /* sparse non-default fill paint records */
    uint32_t *paint_indices_by_shape; /* zero means implicit solid fill */
    size_t paint_count;
    size_t paint_capacity;
    svg_shape_paint *stroke_paints; /* sparse non-default stroke paint records */
    uint32_t *stroke_paint_indices_by_shape; /* zero means solid stroke */
    size_t stroke_paint_count;
    size_t stroke_paint_capacity;
    double *stroke_dash_values; /* compact dash patterns shared by all shapes */
    size_t stroke_dash_value_count;
    size_t stroke_dash_value_capacity;
    svg_paint_stop *paint_stops;
    size_t paint_stop_count;
    svg_shape_clip **clips;
    bool has_clips;
    size_t clip_bytes;
    svg_shape_ignored ignored[SVG_SHAPE_IGNORED_KIND_COUNT];
    svg_anim_document animation;
    base_bytes source; /* borrowed; caller keeps source alive with document */
};

/* out owns decoded arrays and borrows source until document_destroy. Failure leaves out empty. */
svg_shape_error svg_shape_decode(base_bytes source, svg_shape_document *out,
                                 svg_shape_diagnostic *diagnostic);
/* Cancellable variant for long-running validation/import work. Cancellation is
 * reported through out_canceled and leaves out empty. */
svg_shape_error svg_shape_decode_cancellable(
    base_bytes source, svg_xml_cancel_check_fn canceled, void *cancel_context,
    bool *out_canceled, svg_shape_document *out,
    svg_shape_diagnostic *diagnostic);
/* Decodes conditional <switch> children for one injected BCP-47 language. */
svg_shape_error svg_shape_decode_with_system_language(
    base_bytes source, base_bytes system_language, svg_shape_document *out,
    svg_shape_diagnostic *diagnostic);
/* Additive media-aware decode entry point. The document retains decoded image
 * buffers through the provider's release callback and borrows source bytes. */
svg_shape_error svg_shape_decode_with_media(
    base_bytes source, const svg_shape_media_providers *providers,
    svg_shape_document *out, svg_shape_diagnostic *diagnostic);
/* Releases only owned arrays; the borrowed source remains caller-owned. */
void svg_shape_document_destroy(svg_shape_document *document);
const char *svg_shape_error_name(svg_shape_error error);

typedef struct svg_shape_rect {
    double x;
    double y;
    double width;
    double height;
} svg_shape_rect;

typedef struct svg_shape_selection {
    size_t shape_index;
    size_t source_offset;
    size_t source_length;
    svg_shape_rect user_bounds;
    svg_shape_rect device_bounds;
    geom_affine transform;
} svg_shape_selection;

/* Hit-test coordinates and tolerance use decoded document units. */
bool svg_shape_bounds_query(const svg_shape_document *document, size_t shape,
                            svg_shape_selection *out_selection);
bool svg_shape_hit_test(const svg_shape_document *document, double x, double y,
                        double tolerance, svg_shape_selection *out_selection);
/* Resolves an editor byte offset to the most specific rendered source element. */
bool svg_shape_element_at_offset(const svg_shape_document *document,
                                 size_t source_offset,
                                 svg_shape_selection *out_selection);

#endif
#ifndef VEXEL_SVG_SHAPE_MEDIA_H
#define VEXEL_SVG_SHAPE_MEDIA_H

#include "base.h"

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* Per text token budget. */
#define SVG_SHAPE_MEDIA_MAX_TEXT_BYTES (64U * 1024U)
/* Document text budget. The accumulated budget used to be the per-token 64 KiB,
 * which refused any drawing with more than about 64 KiB of labels. */
#define SVG_SHAPE_MEDIA_MAX_DOCUMENT_TEXT_BYTES (64U * 1024U * 1024U)
/* Per text-run budgets: a single span or layout run stays bounded. */
#define SVG_SHAPE_MEDIA_MAX_GLYPHS 65536U
#define SVG_SHAPE_MEDIA_MAX_PATH_COMMANDS 262144U
/* Document budgets. Real drawings carry thousands of labels, so a document-wide
 * budget of 16384 glyphs refused documents a viewer must render; these stay
 * finite so a pathological input is still bounded. */
#define SVG_SHAPE_MEDIA_MAX_DOCUMENT_GLYPHS (1024U * 1024U)
#define SVG_SHAPE_MEDIA_MAX_DOCUMENT_PATH_COMMANDS (4U * 1024U * 1024U)
#define SVG_SHAPE_MEDIA_MAX_FAMILIES 32U
#define SVG_SHAPE_MEDIA_MAX_IMAGE_PIXELS (64U * 1024U * 1024U)

typedef struct svg_shape_text_family {
    const uint8_t *bytes; /* borrowed UTF-8 family name */
    size_t length;
} svg_shape_text_family;

typedef enum svg_shape_text_style {
    SVG_SHAPE_TEXT_NORMAL = 0,
    SVG_SHAPE_TEXT_ITALIC,
    SVG_SHAPE_TEXT_OBLIQUE
} svg_shape_text_style;

typedef struct svg_shape_text_request {
    base_bytes text; /* borrowed UTF-8 */
    const svg_shape_text_family *font_families; /* borrowed */
    size_t font_family_count;
    double size_points;
    double weight;
    svg_shape_text_style style;
    double letter_spacing_points;
} svg_shape_text_request;

typedef enum svg_shape_text_verb {
    SVG_SHAPE_TEXT_MOVE = 0,
    SVG_SHAPE_TEXT_LINE,
    SVG_SHAPE_TEXT_CUBIC,
    SVG_SHAPE_TEXT_CLOSE
} svg_shape_text_verb;

typedef struct svg_shape_text_command {
    svg_shape_text_verb verb;
    double values[6]; /* outline coordinates local to the corresponding glyph */
} svg_shape_text_command;

typedef struct svg_shape_text_glyph {
    double x;
    double y;
    double advance;
    size_t command_start;
    size_t command_count;
} svg_shape_text_glyph;

typedef struct svg_shape_text_layout {
    svg_shape_text_glyph *glyphs; /* owned by the provider */
    size_t glyph_count;
    svg_shape_text_command *commands; /* owned by the provider */
    size_t command_count;
    double advance_width;
    double ascent;
    double descent;
    double leading;
} svg_shape_text_layout;

typedef struct svg_shape_decoded_image {
    const uint8_t *rgba; /* owned by provider; premultiplied RGBA8, top row first */
    size_t byte_count;
    size_t row_stride;
    uint32_t width;
    uint32_t height;
    void *owner; /* provider-private release token */
} svg_shape_decoded_image;

typedef enum svg_shape_media_status {
    SVG_SHAPE_MEDIA_OK = 0,
    SVG_SHAPE_MEDIA_UNSUPPORTED,
    SVG_SHAPE_MEDIA_INVALID,
    SVG_SHAPE_MEDIA_LIMIT,
    SVG_SHAPE_MEDIA_OOM
} svg_shape_media_status;

typedef svg_shape_media_status (*svg_shape_text_layout_fn)(
    void *context, const svg_shape_text_request *request,
    svg_shape_text_layout *out_layout);
typedef void (*svg_shape_text_release_fn)(
    void *context, svg_shape_text_layout *layout);
typedef svg_shape_media_status (*svg_shape_image_decode_fn)(
    void *context, base_bytes encoded, svg_shape_decoded_image *out_image);
typedef void (*svg_shape_image_release_fn)(
    void *context, svg_shape_decoded_image *image);

/* The SVG decoder has no platform dependency. Applications inject these
 * providers; tests may supply deterministic fakes. Provider outputs remain
 * owned until their matching release callback. */
typedef struct svg_shape_media_providers {
    void *context;
    svg_shape_text_layout_fn layout_text;
    svg_shape_text_release_fn release_text;
    svg_shape_image_decode_fn decode_image;
    svg_shape_image_release_fn release_image;
} svg_shape_media_providers;

#endif
#ifndef VEXEL_SVG_SHAPE_ALLOC_H
#define VEXEL_SVG_SHAPE_ALLOC_H

#include <stdbool.h>
#include <stddef.h>

typedef enum svg_shape_alloc_tag {
    SVG_SHAPE_ALLOC_TAG_NONE = 0,
    SVG_SHAPE_ALLOC_TAG_TOKEN_ARRAY,
    SVG_SHAPE_ALLOC_TAG_REFERENCE_INDEX,
    SVG_SHAPE_ALLOC_TAG_CLIP_COPY,
    SVG_SHAPE_ALLOC_TAG_OUTPUT
} svg_shape_alloc_tag;

typedef struct svg_shape_alloc_stats {
    size_t peak_live_bytes;
    size_t live_bytes;
    size_t total_allocated_bytes;
    size_t allocation_count;
    size_t token_array_bytes;
    size_t reference_index_bytes;
    size_t clip_copy_bytes;
    size_t output_bytes;
    bool overflow;
} svg_shape_alloc_stats;

/* The hook is inactive unless a test starts it. It measures allocations routed
 * through the SVG shape/raster modules without changing allocator behavior. */
void svg_shape_alloc_tracking_start(void);
void svg_shape_alloc_tracking_stop(svg_shape_alloc_stats *stats);
void *svg_shape_malloc(size_t size);
void *svg_shape_calloc(size_t count, size_t size);
void *svg_shape_realloc(void *pointer, size_t size);
void svg_shape_free(void *pointer);
bool svg_shape_alloc_set_tag(void *pointer, svg_shape_alloc_tag tag);
void svg_shape_alloc_note_external(void *pointer, size_t size);
void svg_shape_alloc_forget_external(void *pointer);

#endif
#ifndef VEXEL_SVG_PAINT_H
#define VEXEL_SVG_PAINT_H

#include "shape.h"
#include "reference.h"
#include "css.h"

#define SVG_PAINT_MAX_STOPS 65536U
#define SVG_PAINT_MAX_GRADIENT_STOPS 256U
#define SVG_PAINT_CACHE_MAX_GRADIENTS 32768U

typedef struct svg_paint_cache svg_paint_cache;

typedef enum svg_shape_paint_kind {
    SVG_SHAPE_PAINT_SOLID = 0,
    SVG_SHAPE_PAINT_LINEAR,
    SVG_SHAPE_PAINT_RADIAL,
    SVG_SHAPE_PAINT_IMAGE,
    SVG_SHAPE_PAINT_PATTERN
} svg_shape_paint_kind;
typedef enum svg_shape_spread_method {
    SVG_SHAPE_SPREAD_PAD,
    SVG_SHAPE_SPREAD_REFLECT,
    SVG_SHAPE_SPREAD_REPEAT
} svg_shape_spread_method;

struct svg_paint_stop {
    double offset;
    uint8_t rgba[4];
};

struct svg_shape_paint {
    svg_shape_paint_kind kind;
    svg_shape_spread_method spread_method;
    bool object_bounding_box;
    double coordinates[6];
    double bounds[4];
    geom_affine user_inverse;
    geom_affine gradient_inverse;
    size_t first_stop;
    size_t stop_count;
    size_t pattern_index;
    geom_affine pattern_inverse;
    double pattern_opacity;
};

/* Returns an edge pointer only for a nonempty in-range span; formed reports
 * whether pointer arithmetic was used, for deterministic safety tests. */
const geom_edge *svg_paint_edge_span(const svg_shape_document *document,
                                     size_t first_edge, size_t edge_count,
                                     bool *formed);

/* Resolves only supported local linear/radial paint servers. The document owns
 * appended stops; failure leaves both document and paint unchanged. */
svg_shape_error svg_paint_resolve_fill(base_bytes source,
                                       const svg_xml_token *tokens,
                                       size_t token_count,
                                       svg_reference_index *references,
                                       svg_css_sheet *css,
                                       svg_paint_cache **cache,
                                       size_t *token_visits,
                                       svg_xml_span fill,
                                       const geom_edge *edges,
                                       size_t edge_count,
                                       geom_affine user_inverse,
                                       double viewport_width,
                                       double viewport_height,
                                       svg_shape_paint *paint,
                                       svg_paint_stop **stops,
                                       size_t *stop_count,
                                       svg_shape_diagnostic *diagnostic);

void svg_paint_cache_destroy(svg_paint_cache *cache);

void svg_paint_sample(const svg_shape_paint *paint,
                      const svg_paint_stop *stops,
                      double x, double y, uint8_t rgba[4]);

#endif
#ifndef VEXEL_SVG_CLIP_H
#define VEXEL_SVG_CLIP_H

#include "shape.h"
#include "reference.h"
#include "css.h"

typedef struct svg_shape_clip svg_shape_clip;
typedef bool (*svg_clip_boundary_edge_visitor)(void *context, geom_edge edge);
typedef struct svg_clip_work_counts {
    size_t chain_elements;
    size_t child_shapes;
    size_t edges;
} svg_clip_work_counts;

svg_shape_error svg_clip_resolve(base_bytes source,
                                 const svg_xml_token *tokens,
                                 size_t token_count,
                                 svg_reference_index *references,
                                 svg_css_sheet *css,
                                 svg_xml_span value,
                                 svg_shape_document *document,
                                 size_t *document_clip_bytes,
                                 geom_affine user_inverse,
                                 const double local_bounds[4],
                                 size_t owner_node,
                                 svg_shape_clip **out,
                                 svg_shape_diagnostic *diagnostic);
bool svg_clip_local_bounds(const svg_shape_document *document,
                           size_t first_edge, size_t edge_count,
                           geom_affine user_inverse, double bounds[4]);
bool svg_clip_apply_group(svg_shape_document *document,
